const aiLevelSteps = [...document.querySelectorAll(".ai-level-step")];
const aiLevelReaderImageButton = document.querySelector("#ai-level-reader-image-button");
const aiLevelReaderImage = document.querySelector("#ai-level-reader-image");
const aiLevelReaderKicker = document.querySelector("#ai-level-reader-kicker");
const aiLevelReaderTitle = document.querySelector("#ai-level-reader-title");
const aiLevelReaderLead = document.querySelector("#ai-level-reader-lead");
const aiLevelReaderAbout = document.querySelector("#ai-level-reader-about");
const aiLevelReaderUpgrade = document.querySelector("#ai-level-reader-upgrade");
const aiLevelReaderEnough = document.querySelector("#ai-level-reader-enough");
const aiLevelPrev = document.querySelector("#ai-level-prev");
const aiLevelNext = document.querySelector("#ai-level-next");
let activeAiLevel = 0;

function renderAiLevel(index) {
  const level = aiLevelData[index];
  if (!level || !aiLevelReaderImage) return;
  activeAiLevel = index;
  aiLevelSteps.forEach((step, stepIndex) => step.classList.toggle("is-active", stepIndex === index));
  aiLevelReaderImage.src = level.image;
  aiLevelReaderImage.alt = `AI能力等级${level.no}：${level.title}`;
  aiLevelReaderImageButton.dataset.lightboxSrc = level.image;
  aiLevelReaderImageButton.dataset.lightboxAlt = aiLevelReaderImage.alt;
  aiLevelReaderKicker.textContent = level.kicker;
  aiLevelReaderTitle.textContent = level.title;
  aiLevelReaderLead.textContent = level.lead;
  aiLevelReaderAbout.textContent = level.about;
  aiLevelReaderUpgrade.textContent = level.upgrade;
  aiLevelReaderEnough.textContent = level.enough;
  aiLevelPrev.disabled = index === 0;
  aiLevelNext.disabled = index === aiLevelData.length - 1;
}

aiLevelSteps.forEach((step) => step.addEventListener("click", () => renderAiLevel(Number(step.dataset.level))));
aiLevelPrev?.addEventListener("click", () => renderAiLevel(activeAiLevel - 1));
aiLevelNext?.addEventListener("click", () => renderAiLevel(activeAiLevel + 1));

// 首页首屏：干 + 打字动效（一句话一趟，最后收尾一句“还有很多，等着咱们一起干”）
function initHeroTypewriter() {
  const node = document.querySelector(".hero-type .type-text");
  if (!node) return;

  let phrases = [];
  try {
    phrases = JSON.parse(node.dataset.typePhrases || "[]");
  } catch (error) {
    phrases = [];
  }
  if (!phrases.length) return;

  const finale = node.dataset.typeFinale || "";
  const root = node.closest(".hero-type");
  const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  // 用户偏好减少动态时，直接展示完整文案
  if (reduceMotion) {
    node.textContent = [...phrases, finale].filter(Boolean).join("、");
    return;
  }

  const TYPE_MS = 90; // 每打一个字
  const DELETE_MS = 45; // 每收一个字
  const HOLD_MS = 1500; // 一句话打完停留
  const FINALE_HOLD_MS = 3000; // 收尾句停留久一点
  const GAP_MS = 500; // 收回后到下一句的停顿
  const wait = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
  const pageView = node.closest(".page-view");

  async function typeOut(text) {
    for (let i = 1; i <= text.length; i += 1) {
      node.textContent = text.slice(0, i);
      await wait(TYPE_MS);
    }
  }

  async function deleteAll() {
    for (let i = node.textContent.length - 1; i >= 0; i -= 1) {
      node.textContent = node.textContent.slice(0, i);
      await wait(DELETE_MS);
    }
  }

  (async () => {
    // eslint-disable-next-line no-constant-condition
    while (true) {
      for (let p = 0; p < phrases.length; p += 1) {
        // 切到其他页时暂停，回到首页再继续
        if (pageView && pageView.hidden) {
          node.textContent = "";
          await wait(400);
          p -= 1;
          continue;
        }
        await typeOut(phrases[p]);
        await wait(HOLD_MS);
        await deleteAll();
        await wait(GAP_MS);
      }
      // 收尾：还有很多，等着咱们一起干
      if (pageView && pageView.hidden) {
        await wait(400);
        continue;
      }
      root.classList.add("is-finale");
      await typeOut(finale);
      await wait(FINALE_HOLD_MS);
      await deleteAll();
      root.classList.remove("is-finale");
      await wait(GAP_MS + 500);
    }
  })();
}

